Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/Zero.lean"],{"text":"/-\nCopyright (c) 2021 Gabriel Ebner. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Gabriel Ebner, Mario Carneiro\n-/\nmodule\n\nprelude\npublic import Init.Tactics\n\npublic section\n\n/-!\nInstances converting between `Zero α` and `OfNat α (nat_lit 0)`.\n-/\n\ninstance (priority := 300) Zero.toOfNat0 {α} [Zero α] : OfNat α (nat_lit 0) where\n  ofNat := ‹Zero α›.1\n\ninstance (priority := 200) Zero.ofOfNat0 {α} [OfNat α (nat_lit 0)] : Zero α where\n  zero := 0\n\n/-!\nInstances converting between `One α` and `OfNat α (nat_lit 1)`.\n-/\n\ninstance (priority := 300) One.toOfNat1 {α} [One α] : OfNat α (nat_lit 1) where\n  ofNat := ‹One α›.1\n\ninstance (priority := 200) One.ofOfNat1 {α} [OfNat α (nat_lit 1)] : One α where\n  one := 1\n\n/--\nThe fundamental power operation in a monoid.\n`npowRec n a = a*a*...*a` n times.\nThis function should not be used directly; it is often used to implement a `Pow M Nat` instance,\nbut end users should use the `a ^ n` notation instead.\n-/\n@[expose]\ndef npowRec [One M] [Mul M] : Nat → M → M\n  | 0, _ => 1\n  | n + 1, a => npowRec n a * a\n\n/--\nThe fundamental scalar multiplication in an additive monoid.\n`nsmulRec n a = a+a+...+a` n times.\nThis function should not be used directly;\nit is often used to implement an instance for scalar multiplication.\n-/\n@[expose]\ndef nsmulRec [Zero M] [Add M] : Nat → M → M\n  | 0, _ => 0\n  | n + 1, a => nsmulRec n a + a\n","refs":[[16,27,16,40,"9e9c0f532a67",true],[16,46,16,50,"eed636c1cea4",false],[16,56,16,61,"27ab36052eff",false],[17,2,17,7,"8371687c859a",false],[17,12,17,16,"eed636c1cea4",false],[17,20,17,21,"91b057fcbca5",false],[19,27,19,40,"0628231b91a4",true],[19,46,19,51,"27ab36052eff",false],[19,69,19,73,"eed636c1cea4",false],[20,2,20,6,"91b057fcbca5",false],[26,54,26,59,"27ab36052eff",false],[27,2,27,7,"8371687c859a",false],[29,45,29,50,"27ab36052eff",false],[39,21,39,24,"393f18b7f4c6",false],[39,30,39,33,"1a9353d78c15",false],[50,14,50,18,"eed636c1cea4",false],[50,23,50,26,"369f8d4c8855",false],[50,32,50,35,"1a9353d78c15",false]]});
